(async()=>{'use strict';if(new URLSearchParams(location.search).get('profile')!=='exploration-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));let tries=0;while(!window.EmberQA){await wait(100);if(++tries>300)throw Error(document.getElementById('bootNotice').textContent||'boot timeout');}const q=EmberQA,W=EmberTerrain,D=SurvivalData,E=SurvivalExploration,check=(v,s)=>{if(!v)throw Error(s);},fresh=D.fresh();const out=document.createElement('section');out.id='qaOutput';out.style='position:fixed;inset:0;z-index:10000;background:#e8eee7;color:#243d30;overflow:auto;padding:20px';document.body.append(out);const report=document.createElement('pre');report.id='report';out.append(report);const result={};document.getElementById('welcome').hidden=true;q.close(false);q.setPlaying(false);
const pictures=[];async function shot(id,state){q.apply({...structuredClone(fresh),...state});q.close(false);q.setPlaying(!!state.hand);q.world.update(q.state.time,q.state);q.sky.update(q.state,0,true);await wait(1200);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=id;im.alt=id;im.src=q.renderer.domElement.toDataURL('image/png');im.style='width:49%';out.append(im);pictures.push(id);}
check(W.villages.length===6,'village count');result.villages=W.villages.map(v=>({name:v.name,x:v.x,z:v.z}));check(!E.nearestMerchant(fresh),'old shop remains');q.apply({...fresh,...W.merchants[0],money:100});q.shop();document.querySelector('[data-action="shop:buy"]').click();q.trade('buy','wood');check(q.state.inventory.wood===1,'village trade');q.close(false);
result.houses=[];for(const house of q.world.villageHouses.filter((_,i)=>i%3===0)){q.apply({...fresh,x:house.x,z:house.z+9.4,y:W.ground(house.x,house.z+9.4),yaw:0});q.keys({KeyW:true});for(let n=0;n<75;n++)q.move(1/60);q.keys({});result.houses.push({id:house.id,z:q.state.z-house.z,y:q.state.y-house.y});check(Math.abs(q.state.z-house.z)<3.5,'house entrance '+house.id);}
let lake;for(let r=80;r<1800&&!lake;r+=20)for(let a=0;a<6.28;a+=.12){const x=Math.sin(a)*r,z=Math.cos(a)*r,h=W.ground(x,z);if(h<W.water-5&&h>W.water-12&&!W.inCave(x,z,h)){lake={x,z,y:h};break;}}check(lake,'water not found');result.lake=lake;
q.apply({...fresh,x:lake.x,z:lake.z,y:W.water-2.2});q.keys({KeyC:true});q.move(1);q.keys({});check(q.state.y<W.water-4,'cannot dive');q.updateSurvival(10);check(q.state.oxygen===70,'oxygen consumption');q.state.oxygen=0;q.setPlaying(true);q.step(2.2);check(q.state.hp===92,'drowning damage '+q.state.hp);q.keys({Space:true});q.move(5);q.keys({});q.updateSurvival(5);check(q.state.oxygen===100&&q.state.y>=W.water-1.51,'cannot surface');q.setPlaying(false);result.swimming={diving:true,drowning:true,surfaceRecovery:true};
q.apply({...fresh,inventory:{wood:2,ore:3,crystal:1,hammer:1},hand:'hammer'});check(D.knows(q.state,'flashlight'),'lamp locked');q.deposit('flashlight');const pile=q.state.piles[0];q.craft(pile.id,'flashlight');q.work(q.state.jobs[0],10);check(q.state.inventory.flashlight===1,'lamp crafting');q.assignHand(0,'flashlight');check(q.world.itemVisual('sword',true).userData.gripAtOrigin,'sword grip');result.flashlightCrafted=true;q.close(false);
q.apply({...fresh,oxygen:47,flashlightOn:false,checkpoint:{id:'testcamp',x:0,y:fresh.y,z:24}});check(q.saveSlot(18),'save');q.apply(fresh);q.loadSlot(18);check(q.state.oxygen===47&&!q.state.flashlightOn,'save water and lamp');q.close(false);q.setPlaying(false);result.saveCompatible=true;
const temple=W.landmarks.find(l=>l.kind==='temple');q.apply({...fresh,x:temple.x,z:temple.z+20,y:W.ground(temple.x,temple.z+20),yaw:0});q.keys({KeyW:true});for(let n=0;n<170;n++)q.move(1/60);q.keys({});result.templeStairs={z:q.state.z-temple.z,y:q.state.y-temple.y};check(q.state.z<temple.z+4,'temple stairs not climbable');
const v=W.villages[0];await shot('village',{x:v.x,z:v.z+34,y:W.ground(v.x,v.z+34)+2,yaw:0,pitch:-.10});const l=W.landmarks.find(l=>l.kind==='temple');await shot('temple',{x:l.x+4,z:l.z+21,y:W.ground(l.x+4,l.z+21)+2,yaw:.19,pitch:.12});await shot('water-surface',{x:lake.x,z:lake.z,y:W.water+.2,yaw:.4,pitch:-.65});await shot('underwater',{x:lake.x,z:lake.z,y:W.water-3.7,yaw:.4,pitch:-.15});await shot('sword',{...fresh,inventory:{sword:1},hand:'sword',yaw:0,pitch:0});await shot('flashlight',{x:lake.x,z:lake.z,y:W.water-3.7,inventory:{flashlight:1},hand:'flashlight',yaw:.4,pitch:-.15});result.flashlightBeam=q.flashlight.intensity>0;const r=q.world.resources.find(r=>r.id==='start0');await shot('pickup',{x:r.x,z:r.z+4,y:W.ground(r.x,r.z+4),yaw:0,pitch:-.35});q.world.pickupBurst(r.x,r.y+.4,r.z);q.world.updatePickups(.12);q.renderer.render(q.scene,q.camera);document.getElementById('pickup').src=q.renderer.domElement.toDataURL();result.particlePool=q.world.pickupPool.life.length;
const scene=new THREE.Scene();scene.background=new THREE.Color('#dce6df');scene.add(new THREE.HemisphereLight('#ffffff','#68756e',1.2));const sun=new THREE.DirectionalLight('#fff4df',2);sun.position.set(4,9,6);scene.add(sun);const elephant=Wildlife.create(Wildlife.species.find(s=>s.id==='elephant'),q.world.native.originals.fur);scene.add(elephant.model);Wildlife.animate(elephant,0,0,0,0);const cam=new THREE.PerspectiveCamera(44,innerWidth/innerHeight,.1,100);cam.position.set(6,3,-7);cam.lookAt(0,1.8,-.3);q.renderer.render(scene,cam);const im=document.createElement('img');im.id='elephant';im.alt='elephant';im.src=q.renderer.domElement.toDataURL();im.style='width:49%';out.append(im);result.pictures=[...pictures,'elephant'];result.enemies=q.entities.length;result.isolatedElephantRender={pixelRatio:q.renderer.getPixelRatio(),calls:q.renderer.info.render.calls,triangles:q.renderer.info.render.triangles};
q.apply({...fresh,inventory:{wood:4,stone:3,flashlight:1},hand:'flashlight'});q.inventory();result.whiteUI={modal:getComputedStyle(document.getElementById('modal')).backgroundColor,button:getComputedStyle(document.getElementById('newGame')).backgroundColor};q.close(false);
const btn=document.createElement('button');btn.textContent='白い持ち物画面を確認';btn.onclick=()=>{out.hidden=true;q.setPlaying(true);q.inventory();};out.prepend(btn);
report.textContent=JSON.stringify(result,null,2);document.title='探索改良の確認完了';})().catch(e=>{let p=document.getElementById('report')||document.body.appendChild(document.createElement('pre'));p.id='report';p.textContent=e.stack;});
